const BankWorkbook=(()=>{
 const XMLNS='http://schemas.openxmlformats.org/spreadsheetml/2006/main';
 const metaKeys=['name','topic','description','author','version','source','language','date'];
 const esLabels=['Nombre del banco','Tema','Descripción','Autor','Versión','Fuente principal','Idioma','Fecha'];
 const enLabels=['Bank name','Topic','Description','Author','Version','Main source','Language','Date'];
 const safeXml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
 function parseXml(text){if(text.length>64000000||/<!DOCTYPE|<!ENTITY/i.test(text))throw new Error(T('errExpanded'));const xml=new DOMParser().parseFromString(text,'application/xml');if(xml.getElementsByTagName('parsererror').length)throw new Error(T('errFile'));return xml;}
 const nodes=(xml,name)=>Array.from(xml.getElementsByTagNameNS('*',name));
 function checkZip(buffer){const bytes=new Uint8Array(buffer),view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);if(bytes.length>32*1024*1024)throw new Error(T('errSize'));let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(view.getUint32(i,true)===0x06054b50){end=i;break;}if(end<0)throw new Error(T('errFile'));let count=view.getUint16(end+10,true),offset=view.getUint32(end+16,true),total=0;if(count===65535)throw new Error(T('errExpanded'));for(let i=0;i<count;i++){if(offset+46>bytes.length||view.getUint32(offset,true)!==0x02014b50)throw new Error(T('errFile'));const size=view.getUint32(offset+24,true);total+=size;if(size>64*1024*1024||total>128*1024*1024)throw new Error(T('errExpanded'));offset+=46+view.getUint16(offset+28,true)+view.getUint16(offset+30,true)+view.getUint16(offset+32,true);}}
 async function read(file){const buffer=await file.arrayBuffer();checkZip(buffer);const zip=await JSZip.loadAsync(buffer);if(Object.keys(zip.files).some(path=>/vbaProject|macrosheets/i.test(path)))throw new Error(T('errFormula'));const text=async path=>{const entry=zip.file(path);if(!entry)throw new Error(T('errFile'));return entry.async('string');};const workbook=parseXml(await text('xl/workbook.xml')),rels=parseXml(await text('xl/_rels/workbook.xml.rels'));const relations=new Map(nodes(rels,'Relationship').map(n=>[n.getAttribute('Id'),n]));const sheets=nodes(workbook,'sheet');if(['INSTRUCCIONES','INFORMACION','DESAFIOS'].some(name=>!sheets.some(s=>s.getAttribute('name')===name)))throw new Error(T('errSheets'));let strings=[];if(zip.file('xl/sharedStrings.xml'))strings=nodes(parseXml(await text('xl/sharedStrings.xml')),'si').map(n=>nodes(n,'t').map(t=>t.textContent).join(''));
 async function sheet(name){const info=sheets.find(s=>s.getAttribute('name')===name);const relation=relations.get(info.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id')||info.getAttribute('r:id'));if(!relation||relation.getAttribute('TargetMode')==='External')throw new Error(T('errFile'));const target=relation.getAttribute('Target'),path=target.startsWith('/xl/')?target.slice(1):target.startsWith('xl/')?target:'xl/'+target;if(!/^xl\/worksheets\/[^/]+\.xml$/.test(path))throw new Error(T('errFile'));const xml=parseXml(await text(path));if(nodes(xml,'f').length)throw new Error(T('errFormula'));return nodes(xml,'row').map(row=>{const values=[];values._excelRow=Number(row.getAttribute('r'));for(const c of nodes(row,'c')){const address=c.getAttribute('r')||'',letters=address.match(/^[A-Z]+/)?.[0];if(!letters)throw new Error(T('errFile'));let col=0;for(const letter of letters)col=col*26+letter.charCodeAt(0)-64;col--;if(col>100)throw new Error(T('errColumns'));const type=c.getAttribute('t'),raw=nodes(c,'v')[0]?.textContent||'';if(type==='s')values[col]=strings[Number(raw)]??'';else if(type==='inlineStr')values[col]=nodes(c,'t').map(n=>n.textContent).join('');else if(type==='e')throw new Error(T('errFile'));else values[col]=raw;}return values;});}
 await sheet('INSTRUCCIONES');const info=await sheet('INFORMACION'),rows=await sheet('DESAFIOS'),metadata={};for(const row of info){let index=esLabels.indexOf(row[0]);if(index<0)index=enLabels.indexOf(row[0]);if(index>=0)metadata[metaKeys[index]]=row[1]||'';}
 return BankStore.parseRows(rows,metadata);}
 function sheetXml(rows,widths){return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="${XMLNS}"><sheetViews><sheetView workbookViewId="0" showGridLines="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>${widths.map((w,i)=>`<col min="${i+1}" max="${i+1}" width="${w}" customWidth="1"/>`).join('')}</cols><sheetData>${rows.map((row,r)=>`<row r="${r+1}" ht="${r?50:36}" customHeight="1">${row.map((value,c)=>{const ref=String.fromCharCode(65+c)+(r+1);return typeof value==='number'?`<c r="${ref}" s="${r?0:1}"><v>${value}</v></c>`:`<c r="${ref}" s="${r?0:1}" t="inlineStr"><is><t xml:space="preserve">${safeXml(value??'')}</t></is></c>`;}).join('')}</row>`).join('')}</sheetData></worksheet>`;}
 async function templateBytes(){const res=await fetch(`downloads/template-${I18n.lang}.xlsx`);if(!res.ok)throw new Error(T('errFile'));return res.arrayBuffer();}
 function download(bytes,name,type){const blob=new Blob([bytes],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 async function template(){download(await templateBytes(),'Plantilla_Banco_Explorador.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}
 async function exportBank(bank){const zip=await JSZip.loadAsync(await templateBytes());const wb=parseXml(await zip.file('xl/workbook.xml').async('string')),rels=parseXml(await zip.file('xl/_rels/workbook.xml.rels').async('string'));const relations=new Map(nodes(rels,'Relationship').map(r=>[r.getAttribute('Id'),r.getAttribute('Target')]));const path=name=>{const n=nodes(wb,'sheet').find(s=>s.getAttribute('name')===name),id=n.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id')||n.getAttribute('r:id'),target=relations.get(id);return target.startsWith('/')?target.slice(1):'xl/'+target;};const labels=I18n.lang==='es'?esLabels:enLabels;zip.file(path('INFORMACION'),sheetXml(metaKeys.map((key,i)=>[labels[i],bank[key]||'']),[24,90]));zip.file(path('DESAFIOS'),sheetXml([BANK_COLUMNS,...bank.cards.map(c=>[c.id,c.points,Object.entries(CANON_TYPES).find(([,type])=>type===c.type)[0],c.prompt?`${c.question}\n${c.prompt}`:c.question,...c.options,c.correctAnswer,c.reference||'',c.explanation||''])],[18,12,18,60,26,26,26,26,30,25,65]));download(await zip.generateAsync({type:'uint8array',compression:'DEFLATE'}),'Banco_Explorador.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}
 async function kit(){const prompt=await fetch('downloads/Prompt_Generador_Banco.txt');if(!prompt.ok)throw new Error(T('promptPending'));const bytes=await templateBytes(),zip=new JSZip();zip.file('Plantilla_Banco_Explorador.xlsx',bytes);zip.file('Prompt_Generador_Banco.txt',await prompt.arrayBuffer());download(await zip.generateAsync({type:'uint8array',compression:'DEFLATE'}),'Kit_IA_Explorador.zip','application/zip');}
 return {read,template,exportBank,kit,checkZip};
})();
